# seeing if the corners and edges exist, then fill interior

def fill_hollow_rectangles(grid):
    output = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])

    # First pass: identify all rectangular frames and fill their interiors
    changed = True
    while changed:
        changed = False
        for r in range(rows):
            for c in range(cols):
                val = grid[r][c]
                if val < 0 or val > 9:  # Skip invalid values
                    continue

                # Look for this value in all 4 directions from (r,c)
                r_min, r_max = r, r
                c_min, c_max = c, c

                # Scan right to find the rectangle's right edge
                for nc in range(c+1, cols):
                    if grid[r][nc] == val:
                        c_max = nc
                    elif grid[r][nc] != val and output[r][nc] == val:
                        # Found a break in the line
                        break
                    else:
                        break

                # Scan down to find the rectangle's bottom edge
                for nr in range(r+1, rows):
                    if grid[nr][c_max] == val:
                        r_max = nr
                    else:
                        break

                # Now we have a potential rectangle at (r,c) with corner (r_max, c_max)
                # Check if all four corners exist
                corners = [
                    (r, c),
                    (r, c_max),
                    (r_max, c),
                    (r_max, c_max)
                ]
                if all(output[cr][cc] == val for cr, cc in corners):
                    # This is a rectangular frame!
                    # Check if interior cells differ and should be filled
                    min_r, max_r = r, r_max
                    min_c, max_c = c, c_max

                    # Mark as visited by checking corners
                    visited_corners = {(r,c), (r,c_max), (r_max,c), (r_max,c_max)}

                    for rr in range(min_r+1, max_r):
                        for cc in range(min_c+1, max_c):
                            if (rr, cc) not in visited_corners and output[rr][cc] != val:
                                output[rr][cc] = 7
                                changed = True
        break  # Simplified: do one pass per rectangle

    return output

